//! Themes compiled into the binary, so `meteorite new site` and
//! `meteorite theme add <name>` work offline.
//!
//! GENERATED by scripts/gen-bundled.py; do not edit by hand.

use std::fs;
use std::path::Path;

use crate::error::{io_err, Result};

pub struct Bundled {
    pub name: &'static str,
    /// `(path relative to the theme dir, contents)`
    pub files: &'static [(&'static str, &'static str)],
}

impl Bundled {
    /// The version declared in this bundled theme's `theme.yml`.
    pub fn version(&self) -> String {
        self.files
            .iter()
            .find(|(path, _)| *path == "theme.yml")
            .and_then(|(_, text)| {
                text.lines()
                    .find_map(|l| l.strip_prefix("version:"))
                    .map(|v| v.trim().trim_matches('"').to_string())
            })
            .unwrap_or_default()
    }

    pub fn write_to(&self, dir: &Path) -> Result<()> {
        for (rel, body) in self.files {
            let path = dir.join(rel);
            if let Some(parent) = path.parent() {
                fs::create_dir_all(parent).map_err(io_err(parent))?;
            }
            fs::write(&path, body).map_err(io_err(&path))?;
        }
        Ok(())
    }
}

