static ALL: &[&Bundled] = &[&DEFAULT, &DEVLOG, &ORBIT, &TERMINAL];

pub fn find(name: &str) -> Option<&'static Bundled> {
    ALL.iter().copied().find(|b| b.name == name)
}

pub fn names() -> Vec<&'static str> {
    ALL.iter().map(|b| b.name).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;

    /// Every file under assets/themes must be listed, and every listed file must exist.
    #[test]
    fn list_matches_assets_directory() {
        let base = Path::new(env!("CARGO_MANIFEST_DIR")).join("assets/themes");
        for b in ALL {
            let mut on_disk = BTreeSet::new();
            let dir = base.join(b.name);
            let mut stack = vec![dir.clone()];
            while let Some(d) = stack.pop() {
                for e in fs::read_dir(&d).unwrap() {
                    let p = e.unwrap().path();
                    if p.is_dir() {
                        stack.push(p);
                    } else {
                        let rel = p.strip_prefix(&dir).unwrap();
                        on_disk.insert(rel.to_string_lossy().replace('\\', "/"));
                    }
                }
            }
            let listed: BTreeSet<String> = b.files.iter().map(|(p, _)| p.to_string()).collect();
            assert_eq!(
                listed, on_disk,
                "theme `{}`: run `python3 scripts/gen-bundled.py` and rebuild",
                b.name
            );
        }
        let dirs = fs::read_dir(&base).unwrap().count();
        assert_eq!(dirs, ALL.len(), "a theme directory is missing from bundled.rs");
    }
}
